```bscript
let x := 42;
let name := "Alice";
let flag := true;
let pi := 3.14;
```

Reassign (no `let` needed for an existing variable):

```bscript
x := x + 1;
name := "Bob";
```

Delayed initialisation with `null`:

```bscript
let result := null;
result := some_function();
```

---

## Imports

```bscript
import <package_name>;
```

After importing, call functions directly as `<function>(args)`.

```bscript
import healthcare;

let result := analyze_heart_disease(patient_json);
println(result);
```

---

## Builtin Functions

```bscript
println("Hello, world!");   // print with newline
print("no newline");        // print without newline
```

---

## If / Else

```bscript
if (condition) {
    // true branch
} else {
    // false branch
}
```

Example:

```bscript
let score := 75;
if (score >= 50) {
    println("Pass");
} else {
    println("Fail");
}
```

---

## While Loop

```bscript
let i := 0;
while (i < 5) {
    println(i);
    i := i + 1;
}
```

---

## For Loop

```bscript
for (let i := 0; i < 10; i := i + 1) {
    println(i);
}
```

---

## Functions

```bscript
func <name>(<param>, ...) {
    // body
    return <value>;
}
```

Example:

```bscript
func add(a, b) {
    return a + b;
}

let sum := add(3, 4);
println(sum);
```

Functions with no return value omit the `return` statement:

```bscript
func greet(name) {
    println("Hello, " + name);
}
greet("world");
```

