    street: string;
    city:   string;
}

class Order {
    order_id: string;
    quantity: int;
    shipping: Address;
}

let addr := new Address {
    street := "123 Main St",
    city   := "Amsterdam",
};

let order := new Order {
    order_id := "ORD-001",
    quantity := 3,
    shipping := addr,
};

